const T = 1;

const RANGES = {
    s1: [0, 100],
    s2: [-20, 80],
    s3: [0, 100]
};

const text = String(msg.payload).replace(/^\uFEFF/, "");
const sql = [];

try {
    for (const raw of text.split(/\r?\n/)) {
        const line = raw.trim();
        if (!line) continue;

        const parts = line.split(/\s+/);
        const kind = parts.shift();

        // Пропускаем служебные сообщения симулятора.
        if (kind !== "DATA" && kind !== "EVENT") continue;

        const f = {};
        for (const part of parts) {
            const i = part.indexOf("=");
            if (i > 0) {
                f[part.slice(0, i)] = part.slice(i + 1);
            }
        }

        const n = Number(f.n);
        if (!Number.isSafeInteger(n) || n < 1) {
            throw new Error("Некорректный n: " + line);
        }

        const t = n * T;

        if (kind === "DATA") {
            for (const sensor of ["s1", "s2", "s3"]) {
                if (f[sensor] === undefined || f[sensor] === "") {
                    throw new Error("Нет " + sensor + ": " + line);
                }

                const value = Number(f[sensor]);
                if (!Number.isFinite(value)) {
                    throw new Error("Не число " + sensor + ": " + line);
                }

                sql.push(
                    `INSERT INTO readings(n,t_s,sensor,value) ` +
                    `VALUES(${n},${t},'${sensor}',${value});`
                );

                const [min, max] = RANGES[sensor];

                if (value < min || value > max) {
                    sql.push(
                        `INSERT INTO events(n,t_s,type,message) ` +
                        `VALUES(${n},${t},'FAULT',` +
                        `'датчик ${sensor} вне диапазона');`
                    );
                }
            }
        } else {
            if (!["THRESHOLD", "NORMAL"].includes(f.type)) {
                throw new Error("Неизвестный тип события: " + line);
            }

            sql.push(
                `INSERT INTO events(n,t_s,type,message) ` +
                `VALUES(${n},${t},'${f.type}','');`
            );
        }
    }

    if (sql.length === 0) {
        throw new Error("В файле нет строк DATA или EVENT");
    }
} catch (err) {
    node.error(err.message, msg);
    return null;
}

const head =
    "BEGIN;\n" +
    "DELETE FROM readings;\n" +
    "DELETE FROM events;\n" +
    "DELETE FROM sqlite_sequence " +
    "WHERE name IN ('readings','events');\n";

return [
    null,
    {
        payload: head + sql.join("\n") + "\nCOMMIT;\n"
    }
];
